{"op":"define","frontend":"flow","source":"word customer.premium?(customer: Customer) -> Bool {
    effects none
    doc "Returns true exactly when the customer's kind is the ordinal string \"premium\"."
    if ::equals(customer::kind(customer), "premium") { true } else { false }
}

test customer.premium?/exact_premium {
    customer::premium?(customer::new(
        CustomerId::new("00000000-0000-0000-0000-000000000000"),
        Email::new("user@example.com"),
        "premium",
        Money::new(0),
        Instant::new("2000-01-01T00:00:00Z")
    )) => true
}

test customer.premium?/case_mismatch {
    customer::premium?(customer::new(
        CustomerId::new("00000000-0000-0000-0000-000000000000"),
        Email::new("user@example.com"),
        "Premium",
        Money::new(0),
        Instant::new("2000-01-01T00:00:00Z")
    )) => false
}

test customer.premium?/leading_space {
    customer::premium?(customer::new(
        CustomerId::new("00000000-0000-0000-0000-000000000000"),
        Email::new("user@example.com"),
        " premium",
        Money::new(0),
        Instant::new("2000-01-01T00:00:00Z")
    )) => false
}

test customer.premium?/trailing_space {
    customer::premium?(customer::new(
        CustomerId::new("00000000-0000-0000-0000-000000000000"),
        Email::new("user@example.com"),
        "premium ",
        Money::new(0),
        Instant::new("2000-01-01T00:00:00Z")
    )) => false
}

